import re

# Read lesson pairs
with open('/home/ubuntu/runs/paper/qwen-in-glm-hpl-u1-light/frozen/stream-000/play/users/u037/system/state/sessions/01a1ad67-5dcd-75ab-9637-2be79c757586.jsonl', 'r') as f:
    lines = f.readlines()

# Find all demo pairs that have input/output markers
demo_pairs = []
for line in lines:
    try:
        data = json.loads(line)
        if data.get('type') != 'message':
            continue
        content = data.get('message', {}).get('content', [])
        for item in content:
            if item.get('type') != 'text':
                continue
            text = item.get('text', '')
            # Check if this line contains input or output section markers
            if 'Demo pair 1 input (27x21):' in text:
                parts = text.split('\n\n')
                # Find the line with both sections
                if 'Demo pair 1 output (27x10):' in parts[0]:
                    # Parse from this line
                    demo_pairs.append({
                        'input_str': parts[0].split('Demo pair 1 output ')[0],
                        'output_str': parts[0].split('Demo pair 1 output ')[1]
                    })
                    break
    except:
        pass

print(f"Found {len(demo_pairs)} demo pairs to save")
